def lookup_cpt(code: str) -> Optional[Dict]:
    """Lookup CPT procedural billing code."""
    return CPT_PROCEDURE_CATALOGUE.get(code.strip())

def search_cpt_procedures(query: str, limit: int = 20) -> List[Dict]:
    """Search CPT procedural catalog by query."""
    q = query.strip().lower()
    return [p for p in CPT_PROCEDURE_CATALOGUE.values() if q in p["cpt_code"] or q in p["long_description"].lower()][:limit]
